arguments.command:
cd /app && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT table_name, column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'public'
  AND (column_name ILIKE '%proposal%' OR column_name ILIKE '%dashboard%' OR column_name ILIKE '%community%')
ORDER BY table_name, column_name;
" && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT * FROM settings WHERE key ILIKE '%proposal%' OR value ILIKE '%proposal%' ORDER BY key;
SELECT * FROM web_sections;
SELECT 'map_locations_proposal', count(*) FROM map_locations WHERE proposal_id IS NOT NULL;
SELECT 'communities', count(*) FROM communities;
SELECT 'topics', count(*) FROM topics;
SELECT * FROM widget_feeds;
"

cd /app && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT id, key, value FROM settings ORDER BY key;
SELECT * FROM communities;
SELECT id, title, community_id FROM topics;
SELECT * FROM banner_sections;
SELECT id, slug, status FROM site_customization_pages;
SELECT id, name, locale FROM site_customization_content_blocks;
SELECT id, name FROM site_customization_images;
SELECT id, title, segment_recipient, link FROM admin_notifications;
SELECT id, subject, segment_recipient FROM newsletters;
"

cd /app && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT 'proposals_communities' AS src, community_id FROM proposals WHERE community_id IS NOT NULL
UNION ALL SELECT 'budget_investments_communities', community_id FROM budget_investments WHERE community_id IS NOT NULL
UNION ALL SELECT 'legislation_proposals_communities', community_id FROM legislation_proposals WHERE community_id IS NOT NULL
UNION ALL SELECT 'topics_communities', community_id FROM topics WHERE community_id IS NOT NULL;
SELECT id, name, related_type, related_id FROM polls LEFT JOIN poll_translations ON polls.id = poll_translations.poll_id AND locale='en';
SELECT id, proposal_id, poll_id FROM poll_questions WHERE proposal_id IS NOT NULL;
SELECT id, segment_recipient, link FROM admin_notifications;
SELECT id, subject, segment_recipient FROM newsletters;
SELECT id, queue, handler FROM delayed_jobs;
SELECT * FROM signature_sheets;
SELECT * FROM links;
"

cd /app && psql -h /var/lib/postgresql/sockets -U consul -d consul_development -c "
SELECT polls.id, poll_translations.name, related_type, related_id FROM polls LEFT JOIN poll_translations ON polls.id = poll_translations.poll_id AND locale='en';
SELECT id, proposal_id, poll_id FROM poll_questions WHERE proposal_id IS NOT NULL;
SELECT id, segment_recipient, link FROM admin_notifications;
SELECT id, subject, segment_recipient FROM newsletters;
SELECT id, queue, handler FROM delayed_jobs;
SELECT * FROM signature_sheets;
SELECT * FROM links;
"

