// 07. Legislation
// --------------

// Markdown Editor
// ---------------

.markdown-editor {
  background-color: $body-background;

  .markdown-area,
  .markdown-preview {
    display: none;
  }
}

.markdown-editor .markdown-preview {
  height: 15em;
  overflow-y: auto;
}

.markdown-editor textarea {
  height: 15em;
}

.markdown-editor.fullscreen {
  height: 100%;
  left: 0;
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 9999;
}

.markdown-editor.fullscreen .markdown-preview {
  height: 99%;
}

.legislation-admin {
  .menu .is-active > a {
    background: none;
  }
}

// 08. CMS
// --------------
.cms-page-list {

  [class^="icon-"] {
    padding-right: $menu-icon-spacing;
    vertical-align: middle;
  }
}

.legislation-draft-versions-index {

  table tr td {
    padding: 0.25rem 0.375rem;
  }
}

.legislation-questions-form {

  [type]:not([type="submit"]):not([type="file"]):not([type="checkbox"]):not([type="radio"]) {
    margin-bottom: 0;

    @include breakpoint(medium) {
      margin-bottom: 1rem;
    }
  }

  input::placeholder {
    font-style: italic;
  }
}

.fullscreen-container {

  a {
    line-height: 8rem;

    &:active,
    &:focus,
    &:hover {
      text-decoration: none;
    }
  }
}

.fullscreen {

  .fullscreen-container {
    color: color-pick-contrast($admin-color);

    a {
      line-height: 3rem;

      @include breakpoint(medium) {
        float: right;
      }
    }

    .markdown-editor-header {
      display: inline-block;
      vertical-align: top;

      @include breakpoint(medium) {
        line-height: 3rem;
      }
    }

    .truncate {
      @include breakpoint(medium) {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        width: 40vw;
      }
    }

    .markdown-editor-buttons {
      display: block;

      @include breakpoint(medium) {
        display: inline-block;
        float: right;
        padding-left: 1rem;
      }
    }

    input {
      font-size: $small-font-size;
      margin-bottom: 0;
      margin-left: 0;
      margin-top: 1rem;
      padding: 0.5em 1em;

      @include breakpoint(medium) {
        margin: 0.5rem;
      }
    }

    a {
      color: inherit;
    }
  }
}

// 10. Budgets
// -----------------

.columns-selector {

  [class^="icon-"] {
    vertical-align: middle;
  }

  &[aria-expanded="false"] {
    @include hollow-button;

    + .columns-selector-wrapper {
      display: none;
    }
  }

  &[aria-expanded="true"] {
    @include regular-button;
  }
}

.columns-selector-wrapper {
  background: $light-gray;
  border-radius: 10px;
  margin-bottom: 1rem;
  padding: 2rem;

  .column-selector-item {
    display: inline-block;

    &.hidden {
      display: none;
    }

    label {
      font-size: $base-font-size;
      line-height: 1.5rem;
    }
  }
}

.column-selectable {

  .hidden {
    display: none;
  }
}

// 11. Newsletters
// -----------------

.admin .newsletter-body-content {

  table,
  tbody,
  tr,
  th,
  td {
    border: 0;

    &:nth-child(even),
    &:nth-child(even) td:last-child,
    &:nth-child(odd) td:last-child,
    &:hover {
      background: none;
    }
  }
}
